local config = {
  ui_story_5044_50440001_1_dialog_content = "*Kerumunan bergumam*",
  ui_story_5044_50440001_2_dialog_content = "*Kerumunan bergumam*",
  ui_story_5044_50440001_3_dialog_content = "Ada keributan apa? Apa yang terjadi di sini?",
  ui_story_5044_50440001_4_dialog_content = "PlayerName!",
  ui_story_5044_50440001_5_dialog_content = "Itu suara Vice! Kamu ada di mana, Vice?",
  ui_story_5044_50440001_6_dialog_content = "PlayerName! Aku di sini! Cepat datang!",
  ui_story_5044_50440001_7_dialog_content = "Apa yang terjadi?",
  ui_story_5044_50440001_8_dialog_content = "Selamat datang ke <color=#FFB400>Penjahat Super Gronkenstein Ruu</color> tempat bermain!",
  ui_story_5044_50440001_9_dialog_content = "Siapa yang ingin bermain selanjutnya?",
  ui_story_5044_50440001_10_dialog_content = "Gronru? Apa ini...?",
  ui_story_5044_50440001_11_dialog_content = "Ini adalah mesin game saya yang baru dikembangkan, Navigator!",
  ui_story_5044_50440001_12_dialog_content = "Kau melakukan omong kosong seperti ini pada Colossus lagi? Bukankah Illumina membuat Anda cukup sibuk dengan pekerjaan?",
  ui_story_5044_50440001_13_dialog_content = "Ini adalah pekerjaan saya! Saya akan menggunakan game ini untuk menguji kecerdasan dan kecepatan reaksi Anda!",
  ui_story_5044_50440001_14_dialog_content = "Apakah kalian semua sudah memainkannya? Apa hasil Anda?",
  ui_story_5044_50440001_15_dialog_content = "Saya berhasil! Koordinasi tangan-mata saya sangat cepat!",
  ui_story_5044_50440001_16_dialog_content = "Bodoh, itu bukan skormu—berapa kali kamu mati.",
  ui_story_5044_50440001_17_dialog_content = "Apa!?",
  ui_story_5044_50440001_18_dialog_content = "Sialan, orang-orang Illumina itu benar-benar licik, aku akan memberi mereka itu!",
  ui_story_5044_50440001_19_dialog_content = "Saya pikir Petugas permainan Gronru dirancang sangat menarik.",
  ui_story_5044_50440001_20_dialog_content = "Apakah Anda menyelesaikannya, Axelia?",
  ui_story_5044_50440001_21_dialog_content = "Yap, selesai dan selesai.",
  ui_story_5044_50440001_22_dialog_content = "Saat ini, tim kami memiliki skor tertinggi di seluruh permainan.",
  ui_story_5044_50440001_23_dialog_content = "Wow! Apakah kamu serius?",
  ui_story_5044_50440001_24_dialog_content = "Kami menyalip tim Hiiro dan merebut tempat pertama di saat-saat terakhir, bukan?",
  ui_story_5044_50440001_25_dialog_content = "... Anda memiliki potensi.",
  ui_story_5044_50440001_26_dialog_content = "Bahkan Hiiro dimainkan? Saya kira saya akan mencobanya!",
  ui_story_5044_50440001_27_dialog_content = "Heehee, aku sangat ingin kamu bermain, PlayerName!",
  ui_story_5044_50440001_28_dialog_content = "Bisakah Anda menjelaskannya kepada saya terlebih dahulu, Gronru? Bagaimana Anda memainkan game ini?",
  ui_story_5044_50440001_29_dialog_content = "Ini sangat sederhana. Pada dasarnya, ini adalah game kasual side-scrolling dengan aspek edutainment sebagai intinya.",
  ui_story_5044_50440001_30_dialog_content = "Sisi... berjalan-jalan apa?",
  ui_story_5044_50440001_31_dialog_content = "Maksud Anda, ini semua tentang menggulung gulungan ke samping?",
  ui_story_5044_50440001_32_dialog_content = "Anda hanya perlu menekan tombol ini pada saat yang tepat untuk menghindari atau mengalahkan musuh Anda.",
  ui_story_5044_50440001_33_dialog_content = "Dapatkah saya menggunakan Rapid Torrent?",
  ui_story_5044_50440001_34_dialog_content = "Fitur itu tidak tersedia saat ini.",
  ui_story_5044_50440001_35_dialog_content = "Bagaimana jika saya menekan lebih keras?",
  ui_story_5044_50440001_36_dialog_content = "... Itu juga tidak akan berhasil.",
  ui_story_5044_50440001_37_dialog_content = "Oh...",
  ui_story_5044_50440001_38_dialog_content = "Apakah Anda bermain atau tidak?",
  ui_story_5044_50440001_39_dialog_content = "Kami bermain, tentu saja! Mari kita lakukan!",
  ui_story_5044_50440001_40_dialog_content = "Nah, game ini membutuhkan grup yang terdiri dari tiga orang, dan Anda dan Vice hanya membuat dua.",
  ui_story_5044_50440001_41_dialog_content = "Bisakah saya bergabung?",
  ui_story_5044_50440001_42_dialog_content = "Carleen! Kamu di sini juga!?",
  ui_story_5044_50440001_43_dialog_content = "Itu benar. Saya datang segera setelah menerima kabar dari Vice. Bagaimana kita memainkan game ini?",
  ui_story_5044_50440001_44_dialog_content = "Cukup tekan tombol ini pada waktu yang tepat untuk menghindar atau menyerang.",
  ui_story_5044_50440001_45_dialog_content = "Bisakah saya menggunakan Bunga Es?",
  ui_story_5044_50440001_46_dialog_content = "Tidak.",
  ui_story_5044_50440001_47_dialog_content = "Jika saya...",
  ui_story_5044_50440001_48_dialog_content = "<size=45>Tidak masalah seberapa keras Anda menekan tombol! Apa otakmu hanya berisi otot atau semacamnya!?</size>",
  ui_story_5044_50440001_49_dialog_content = "Tidak membiarkan seorang pejuang menggunakan kekuatan penuh mereka adalah rasa tidak hormat terbesar kepada lawan mereka.",
  ui_story_5044_50440001_50_dialog_content = "Tapi sejak Vice mengundang saya ke sini, saya bersedia untuk melihat sekilas.",
  ui_story_5044_50440001_51_dialog_content = "Jadi, itulah tim kami yang terdiri dari tiga orang, siap untuk memulai!",
  ui_story_5044_50440001_52_dialog_content = "Kita mulai permainannya!",
  ui_story_5044_50440001_53_dialog_content = "Katakan padanya untuk menyingkirkan tombak itu. Dia akan menusuk mesin permainanku!",
  ui_story_5044_50440101_1_dialog_content = "Ini akan dimulai! Aku sangat gembira!",
  ui_story_5044_50440101_2_dialog_content = "Level pertama tidak terlalu sulit, jadi harap santai saja.",
  ui_story_5044_50440101_3_dialog_content = "Terimakasih atas peringatannya!",
  ui_story_5044_50440101_4_dialog_content = "(Jika kita gagal di level pertama, itu akan memalukan...)",
  ui_story_5044_50440101_5_dialog_content = "Jangan khawatir tentang itu, PlayerName.",
  ui_story_5044_50440101_6_dialog_content = "Hah? Bagaimana Anda tahu apa yang saya pikirkan, Vice?",
  ui_story_5044_50440101_7_dialog_content = "Aku tahu dari ekspresimu. Itu tampilan yang Anda dapatkan sebelum kita bertarung dalam pertempuran besar.",
  ui_story_5044_50440101_8_dialog_content = "Hei, tidakkah menurutmu membandingkan bermain game dengan melawan Eclipsites terlalu berlebihan?",
  ui_story_5044_50440101_9_dialog_content = "Mari kita mulai. Tombak saya akan menembus semua kegelapan dengan kekuatan cahaya.",
  ui_story_5044_50440101_10_dialog_content = "Sudah kubilang singkirkan senjatamu!",
  ui_story_5044_50440201_1_dialog_content = "Tingkat pertama benar-benar sangat mudah!",
  ui_story_5044_50440201_2_dialog_content = "Ya, kamu terbakar, PlayerName! Pernahkah Anda melakukan ini sebelumnya?",
  ui_story_5044_50440201_3_dialog_content = "Saya harus mengatakan, Navigator benar-benar memiliki bakat alami untuk bermain game.",
  ui_story_5044_50440201_4_dialog_content = "Yang paling mengejutkan saya tentang semua ini adalah Petugas itu Gronru benar-benar menambahkan kita semua sebagai karakter game!",
  ui_story_5044_50440201_5_dialog_content = "Rasanya luar biasa melihat saya yang kecil terpental di dalam game!",
  ui_story_5044_50440201_6_dialog_content = "Tapi bagaimana Anda tahu kami benar-benar datang dan bermain?",
  ui_story_5044_50440201_7_dialog_content = "Heh...",
  ui_story_5044_50440201_8_dialog_content = "Mungkinkah Anda mendesain karakter berdasarkan semua orang di atas Colossus?",
  ui_story_5044_50440201_9_dialog_content = "Itu benar! Saya pikir itu akan membuat rasa pencelupan menjadi lebih kuat!",
  ui_story_5044_50440201_10_dialog_content = "Proyek yang sangat besar!",
  ui_story_5044_50440201_11_dialog_content = "Ini bukan masalah besar, hanya beberapa ratus desain. Saya meminta orang-orang dari lab untuk bekerja lembur sebentar untuk menyelesaikan ini.",
  ui_story_5044_50440201_12_dialog_content = "...",
  ui_story_5044_50440201_13_dialog_content = "Baiklah, mari kita lanjutkan permainannya, ya? Tingkat kedua sedang menunggu Anda!",
  ui_story_5044_50440301_1_dialog_content = "Kemenangan mulus lainnya! Pertahankan ini dan kami akan menyelesaikan permainan dalam waktu singkat!",
  ui_story_5044_50440301_2_dialog_content = "hehehe, PlayerNamekecepatan reaksinya sangat cepat, tapi mari kita lihat apakah kamu bisa menyelesaikan bos terakhir!",
  ui_story_5044_50440301_3_dialog_content = "Jangan sombong, PlayerName. Skor kami jauh dari tempat pertama.",
  ui_story_5044_50440301_4_dialog_content = "*Kerumunan bergumam*",
  ui_story_5044_50440301_5_dialog_content = "Uh-oh, orang-orang datang untuk menonton...",
  ui_story_5044_50440301_6_dialog_content = "Jangan gugup—semua orang ada di sini untuk mendukung Anda.",
  ui_story_5044_50440301_7_dialog_content = "Biarkan aku bertaruh lagi! Kali ini saya yakin Navigator tidak dapat mencapai level keempat!",
  ui_story_5044_50440301_8_dialog_content = "Apa? Dia bahkan tidak bisa melewati level ketiga!",
  ui_story_5044_50440301_9_dialog_content = "Baiklah, pasang taruhanmu.",
  ui_story_5044_50440301_10_dialog_content = "Apa yang kamu pikir kamu lakukan !? Jangan pernah berpikir untuk berjudi di Colossus saya!",
  ui_story_5044_50440301_11_dialog_content = "Kunci Pas Rediesel itu! Jangan membuatku datang ke sana!",
  ui_story_5044_50440301_12_dialog_content = "Astaga! Saya keluar dari sini!",
  ui_story_5044_50440301_13_dialog_content = "Jangan biarkan mereka mengalihkan perhatian Anda, PlayerName. Ayo lanjutkan.",
  ui_story_5044_50440401_1_dialog_content = "Kami berhasil melewati level ketiga semulus level kedua. Game ini sebenarnya tidak sesulit yang saya harapkan.",
  ui_story_5044_50440401_2_dialog_content = "Mungkin kita bisa mengambil posisi teratas dalam sekali percobaan!",
  ui_story_5044_50440401_3_dialog_content = "Hei, jangan remehkan permainanku, Vice...",
  ui_story_5044_50440401_4_dialog_content = "Petugas, apakah itu berarti sesuatu yang mengerikan sedang menunggu kita di level berikutnya?",
  ui_story_5044_50440401_5_dialog_content = "Mampu menangani situasi apa pun yang menghadang adalah penting, tetapi momentum adalah hal yang paling penting di medan perang.",
  ui_story_5044_50440401_6_dialog_content = "Carleen benar! Pertahankan semangat tinggi — bahkan jika Anda tiba-tiba kehilangan segalanya dan harus memulai dari awal ...",
  ui_story_5044_50440401_7_dialog_content = "Itu adalah hal yang menguji ketabahan seseorang!",
  ui_story_5044_50440401_8_dialog_content = "Itu tidak akan terjadi pada kita, benar, PlayerName?",
  ui_story_5044_50440401_9_dialog_content = "Ayo! Anda punya ini!",
  ui_story_5044_50440401_10_dialog_content = "PlayerName sedang menyemangati dirinya sendiri?",
  ui_story_5044_50440401_11_dialog_content = "Dia sangat gugup—dia berkeringat dingin.",
  ui_story_5044_50440401_12_dialog_content = "Oke, ayo cepat ke level selanjutnya!",
  ui_story_5044_50440401_13_dialog_content = "Semoga beruntung, PlayerName!",
  ui_story_5044_50440501_1_dialog_content = "Kami semakin dekat dan semakin dekat ke level akhir!",
  ui_story_5044_50440501_2_dialog_content = "Tetap bertahan, PlayerName! Kami baik-baik saja!",
  ui_story_5044_50440501_3_dialog_content = "Memang. Tampaknya jika Anda terus seperti itu, Anda dapat langsung menuju peringkat teratas.",
  ui_story_5044_50440501_4_dialog_content = "Anda tidak pernah bisa meremehkan anak-anak muda ini! Saya tidak pernah mengira Navigator memilikinya di dalam dirinya!",
  ui_story_5044_50440501_5_dialog_content = "Hei, apa yang kalian lakukan di sini daripada bermain-main denganku?",
  ui_story_5044_50440501_6_dialog_content = "Komandan! Kami sedang menonton Navigator memainkan game ini!",
  ui_story_5044_50440501_7_dialog_content = "Anda sedang menonton dia bermain game? Di mana kesenangannya?",
  ui_story_5044_50440501_8_dialog_content = "Skornya melonjak sangat tinggi sekarang! Ini sangat intens!",
  ui_story_5044_50440501_9_dialog_content = "Ini sangat kekanak-kanakan. Siapa peduli!?",
  ui_story_5044_50440501_10_dialog_content = "Kekanak-kanakan? Barton, ini adalah produk terbaru dari laboratorium penelitian kami! Tidak ada yang bisa dianggap enteng!",
  ui_story_5044_50440501_11_dialog_content = "Benar, Sio?",
  ui_story_5044_50440501_12_dialog_content = "Ah... Hah? Maaf, aku tertidur sambil berdiri...",
  ui_story_5044_50440501_13_dialog_content = "(Bagaimana kamu bisa tertidur seperti itu !? Berapa banyak waktu lembur yang dia lakukan?)",
  ui_story_5044_50440501_14_dialog_content = "Kami tidak membutuhkan sikap seperti itu di sini, terima kasih banyak!",
  ui_story_5044_50440501_15_dialog_content = "PlayerName, apakah Anda siap untuk mengambil tingkat berikutnya?",
  ui_story_5044_50440501_16_dialog_content = "R-Siap! Mari kita lakukan!",
  ui_story_5044_50440501_17_dialog_content = "Nah, begitu, dong, PlayerName!",
  ui_story_5044_50440501_18_dialog_content = "Tidak peduli siapa atau apa musuh kita berikutnya, biarkan aku melakukannya!",
  ui_story_5044_50440501_19_dialog_content = "Tombak! Awasi tombakmu!",
  ui_story_5044_50440601_1_dialog_content = "...",
  ui_story_5044_50440601_2_dialog_content = "...",
  ui_story_5044_50440601_3_dialog_content = "Akhirnya, level terakhir... Anda bisa merasakan ketegangan di udara...",
  ui_story_5044_50440601_4_dialog_content = "Ehehehe...",
  ui_story_5044_50440601_5_dialog_content = "<size=45>Yehehehehe!</size>",
  ui_story_5044_50440601_6_dialog_content = "Petugas Gronru, ada apa dengan tawa menyeramkan itu?",
  ui_story_5044_50440601_7_dialog_content = "Upaya yang mengagumkan... Saya tidak menyangka Anda benar-benar berhasil sejauh ini...",
  ui_story_5044_50440601_8_dialog_content = "Bawahanku gagal menghentikanmu, jadi sepertinya sekarang aku...",
  ui_story_5044_50440601_9_dialog_content = "aku sekarang... er...",
  ui_story_5044_50440601_10_dialog_content = "\"Aku sekarang tidak punya pilihan selain mengakui kekuatanmu ...\"",
  ui_story_5044_50440601_11_dialog_content = "Saya sekarang tidak punya pilihan selain mengakui kekuatan Anda!",
  ui_story_5044_50440601_12_dialog_content = "Tapi melawan Penjahat Super Gronkenstein Ruu...",
  ui_story_5044_50440601_13_dialog_content = "\"Kamu sama saja dengan mati ...\"",
  ui_story_5044_50440601_14_dialog_content = "Anda sama saja sudah mati! Hahahahaha!",
  ui_story_5044_50440601_15_dialog_content = "<size=32>Dia berperan sebagai penjahat terhebat saat ini, benar?</size>",
  ui_story_5044_50440601_16_dialog_content = "<size=32>Sepertinya begitu, tapi dia kesulitan mengingat dialognya.</size>",
  ui_story_5044_50440601_17_dialog_content = "<size=32>Apakah kita akan melakukan ini?</size>",
  ui_story_5044_50440601_18_dialog_content = "<size=45>Jadi, kaulah yang berada di balik semua ini!?</size>",
  ui_story_5044_50440601_19_dialog_content = "<size=45>Aku tidak akan pernah memaafkanmu karena membahayakan sekutuku!</size>",
  ui_story_5044_50440601_20_dialog_content = "<size=32>Carleen benar-benar masuk ke dalamnya ...</size>",
  ui_story_5044_50440601_21_dialog_content = "Kami akan menjatuhkanmu di tempatmu berdiri—",
  ui_story_5044_50440601_22_dialog_content = "<size=45>Vila Super Gronkenstank!</size>",
  ui_story_5044_50440601_23_dialog_content = "Kau bahkan tidak ingat namaku!? Jangan berharap aku bersikap lunak padamu!",
  ui_story_5044_50440601_24_dialog_content = "Biarkan bos terakhir bertarung—mulai!",
  ui_story_5044_50440602_1_dialog_content = "Kita berhasil!",
  ui_story_5044_50440602_2_dialog_content = "Aku tahu gonggongannya lebih buruk daripada gigitannya, PlayerName.",
  ui_story_5044_50440602_3_dialog_content = "Untuk sesaat, saya pikir kami akan dirampok dari semua yang telah kami capai sampai sekarang.",
  ui_story_5044_50440602_4_dialog_content = "Tidak buruk. Anda bahkan berhasil mengalahkan level terakhir yang saya rancang dengan susah payah.",
  ui_story_5044_50440602_5_dialog_content = "Saya kira ini berarti saya perlu mencari waktu untuk menyesuaikan kesulitannya!",
  ui_story_5044_50440602_6_dialog_content = "Beri kami hasilnya! Berapa skor akhir kita?",
  ui_story_5044_50440602_7_dialog_content = "Biarkan saya memeriksa papan peringkat ...",
  ui_story_5044_50440602_8_dialog_content = "Apa!?",
  ui_story_5044_50440602_9_dialog_content = "Ada apa?",
  ui_story_5044_50440602_10_dialog_content = "Kamu mengalahkan tim Axelia dan menjadi—",
  ui_story_5044_50440602_11_dialog_content = "<size=45>Nomor satu!</size>",
  ui_story_5044_50440602_12_dialog_content = "Luar biasa! Kami berhasil mencapai posisi pertama!",
  ui_story_5044_50440602_13_dialog_content = "Yah, tentu saja.",
  ui_story_5044_50440602_14_dialog_content = "Anda bermain sangat baik, PlayerName. Saya terkesan.",
  ui_story_5044_50440602_15_dialog_content = "Saya harapkan tidak kurang dari Navigator kami. Bahkan di Illumina, kehebatan dalam beradaptasi dengan situasi yang berbeda dianggap tingkat pertama.",
  ui_story_5044_50440602_16_dialog_content = "Seperti yang saya katakan sebelumnya, anak ini adalah real deal!",
  ui_story_5044_50440602_17_dialog_content = "Kapan kamu kembali? Bukankah Anda mengatakan permainan ini \"kekanak-kanakan\"?",
  ui_story_5044_50440602_18_dialog_content = "<size=32>Komandan Barton berdiri di kejauhan barusan, menatap permainan seperti orang kesurupan...</size>",
  ui_story_5044_50440602_19_dialog_content = "Datang dan terima hadiahmu, PlayerName.",
  ui_story_5044_50440602_20_dialog_content = "Hadiah? Kami mendapat hadiah? Apa itu!?",
  ui_story_5044_50440602_21_dialog_content = "Hadiah utama untuk tempat pertama adalah—",
  ui_story_5044_50440602_22_dialog_content = "Bebek karet kuning bahagia yang sangat keren ini!",
  ui_story_5044_50440602_23_dialog_content = "...",
  ui_story_5044_50440602_24_dialog_content = "...",
  ui_story_5044_50440602_25_dialog_content = "Ada apa dengan kalian semua? Laboratorium penelitian memiliki dana yang sangat terbatas, saya ingin Anda tahu! Pengemis tidak bisa menjadi pemilih, jadi ambil saja bebek sialan itu!",
  ui_story_5044_50440602_26_dialog_content = "Dan bebek kuning kecil ini menggemaskan sekali!",
  ui_story_5044_50440602_27_dialog_content = "Tapi sebagai hadiah utama untuk mengambil tempat pertama, itu sedikit...",
  ui_story_5044_50440602_28_dialog_content = "<size=45>Sedikit luar biasa apa adanya! Aku ingin bebek kuning kecil itu untuk diriku sendiri!</size>",
  ui_story_5044_50440602_29_dialog_content = "Sudah beres—saya ingin pertandingan ulang! Aku akan menang kali ini!",
  ui_story_5044_50440602_30_dialog_content = "Mungkin di kehidupan selanjutnya, Brock.",
  ui_story_5044_50440602_31_dialog_content = "Sepertinya seseorang tidak senang dengan hasilnya. Apa yang harus kita lakukan...?",
  ui_story_5044_50440602_32_dialog_content = "Hah! Untungnya, Anda masih memiliki kesempatan untuk membalikkan keadaan!",
  ui_story_5044_50440602_33_dialog_content = "Level tadi adalah tahap terakhir dari kampanye dasar. Yang benar adalah...",
  ui_story_5044_50440602_34_dialog_content = "Ada yang super spesial <color=#FFB400>Modus Tanpa Akhir</color> masih menunggumu!",
  ui_story_5044_50440602_35_dialog_content = "Musuh tak berujung — bergegas ke arahmu, gelombang demi gelombang tak terbatas!",
  ui_story_5044_50440602_36_dialog_content = "Jika Anda menginginkan skor yang lebih tinggi, Anda tahu apa yang harus dilakukan!",
  ui_story_5044_50440602_37_dialog_content = "\"Mode Tanpa Akhir\"? Saya tidak sabar untuk melihat ini!",
  ui_story_5044_50440602_38_dialog_content = "Aku! saya selanjutnya! Saya ingin mencoba!",
  ui_story_5044_50440602_39_dialog_content = "Iya, aku juga!",
  ui_story_5044_50440602_40_dialog_content = "Begitu banyak tim yang sangat ingin mendapat kesempatan bermain, sekarang!",
